function renderChapterTabs() {
    const el = document.getElementById('chapterTabs');
    const allNames = [REGION_KEY, ...CHAPTER_NAMES];
    el.innerHTML = allNames.map(name => `
        <button class="chapter-btn${name === currentChapter ? ' active' : ''}" data-chapter="${name}">${name === REGION_KEY ? '🏆 ' + REGION_KEY : name + '分會'}</button>
    `).join('');
    el.querySelectorAll('.chapter-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            currentChapter = btn.dataset.chapter;
            currentMonths = defaultMonths(monthsAvailableFor(currentChapter));
            renderChapterTabs();
            renderMonthTabs();
            renderAll();
        });
    });

