    )

# 2. name cell markup (both occurrences)
old_cell = '<td class="name">{{ r.member.name }}</td>'
new_cell = '<td class="name">{{ r.member.name }}<div class="name-summary">來賓<span data-summary="guests" class="{{ \'zero\' if not r.stats.totals.guests }}">{{ r.stats.totals.guests }}人</span>・早鳥<span data-summary="early_bird" class="{{ \'zero\' if not r.stats.totals.early_bird }}">{{ r.stats.totals.early_bird }}次</span>・121<span data-summary="ones" class="{{ \'zero\' if not r.stats.totals.ones }}">{{ r.stats.totals.ones }}次</span>・咖啡<span data-summary="coffee" class="{{ \'zero\' if not r.stats.totals.coffee }}">{{ r.stats.totals.coffee }}場</span></div></td>'
c = c.replace(old_cell, new_cell)

# 3. JS update block
old_js = """                    if (totalCells[idx]) totalCells[idx].textContent = data.totals[metric] + units[metric];
                    if (streakCells[idx]) {
                        streakCells[idx].textContent = fmtStreak(data.streaks[metric]);
